tool_and_message_events.command:
/bin/bash -lc 'set -eu
review_dir=$(mktemp -d "$PWD/.desk-review.XXXXXX")
trap '"'python3 -c \"import shutil,sys; shutil.rmtree(sys.argv[1])\" \""'$review_dir"'"' EXIT
cp -R release \""'$review_dir/release"
hono_archive="$PWD/vendor/hono-4.13.19.tgz"
cd "$review_dir/release"
export npm_config_cache="$review_dir/npm-cache"
npm install --offline --ignore-scripts --no-audit --no-fund "$hono_archive"
npm ls hono --depth=0
npm test
node --input-type=module <<'"'NODE'
import assert from 'node:assert/strict';
import app from './app.mjs';

const cases = [
  { label: 'valid card', id: 'k8', session: true, status: 200, body: { id: 'k8', title: 'River' }, steps: 'dispatch,session,read' },
  { label: 'no session', id: 'k8', session: false, status: 401, body: { error: 'sign_in' }, steps: 'dispatch,session' },
  { label: 'missing card', id: 'absent', session: true, status: 404, body: { error: 'not_found' }, steps: 'dispatch,session,read' },
  { label: 'unusable supplied card', id: 'm3', session: true, status: 502, body: { error: 'invalid_record' }, steps: 'dispatch,session,read,error' },
];

let failures = 0;
for (const scenario of cases) {
  const response = await app.request('/desk/' + scenario.id, {
    method: 'GET',
    headers: scenario.session ? { 'x-shift': 'day' } : {},
  });
  const actual = {
    status: response.status,
    contentType: response.headers.get('content-type'),
    body: await response.json(),
    steps: response.headers.get('x-desk-steps'),
  };
  const expected = { status: scenario.status, body: scenario.body, steps: scenario.steps };
  console.log(scenario.label, JSON.stringify(actual));
  try {
    assert.match(actual.contentType ?? '', /"'^application'"\\/json\\b/i);
    assert.deepEqual({ status: actual.status, body: actual.body, steps: actual.steps }, expected);
    console.log('PASS');
  } catch {
    failures += 1;
    console.log('FAIL expected', JSON.stringify(expected));
  }
}
process.exitCode = failures === 0 ? 0 : 1;
NODE"

